const { spawn } = require("child_process");
const fs = require("fs");
const path = require("path");

// Try playwright from common locations
async function main() {
  let chromium;
  try {
    const pw = require("<HOME>/.local/lib/node_modules/playwright");
    chromium = pw.chromium;
  } catch (e) {
    try {
      const pw = require("playwright");
      chromium = pw.chromium;
    } catch (e2) {
      console.error("no playwright", e2.message);
      process.exit(2);
    }
  }

  const browser = await chromium.launch({
    executablePath: "<HOME>/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome",
    headless: true,
  });

  // Desktop
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await page.goto("http://<LAN_IP>:8765/index.html", { waitUntil: "networkidle" });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: "<TMP>/ramen-desktop.png", fullPage: true });

  // Move mouse to interact
  await page.mouse.move(900, 400);
  await page.waitForTimeout(600);
  await page.screenshot({ path: "<TMP>/ramen-desktop-mouse.png" });

  // Mobile
  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(500);
  await page.screenshot({ path: "<TMP>/ramen-mobile.png" });

  // Check for JS errors
  const errors = [];
  page.on("pageerror", (err) => errors.push(String(err)));
  await page.reload({ waitUntil: "networkidle" });
  await page.waitForTimeout(800);

  // reduced motion
  const ctx = await browser.newContext({
    viewport: { width: 1280, height: 800 },
    reducedMotion: "reduce",
  });
  const page2 = await ctx.newPage();
  const errs2 = [];
  page2.on("pageerror", (e) => errs2.push(String(e)));
  await page2.goto("http://<LAN_IP>:8765/index.html", { waitUntil: "networkidle" });
  await page2.waitForTimeout(800);
  await page2.screenshot({ path: "<TMP>/ramen-reduced.png" });

  console.log("errors_desktop", errors);
  console.log("errors_reduced", errs2);
  console.log("ok");
  await browser.close();
}
main().catch((e) => { console.error(e); process.exit(1); });
'

