    return [d[0], d[1], d[2]];
  });

  // Mobile
  await page.setViewport({ width: 390, height: 844 });
  await new Promise(r => setTimeout(r, 600));
  await page.screenshot({ path: '<TMP>/ramen-mobile2.png' });
  const mobileSamples = await page.evaluate(() => {
    const c = document.getElementById('scene');
    const ctx = c.getContext('2d');
    const w = c.width, h = c.height;
    const at = (nx, ny) => {
      const d = ctx.getImageData(Math.floor(nx * w), Math.floor(ny * h), 1, 1).data;
      return [d[0], d[1], d[2]];
    };
    // Check bottom edge isn't cutting bowl - sample mid-lower area for ceramic
    return { mid: at(0.5, 0.55), lower: at(0.5, 0.72), bottom: at(0.5, 0.95), steam: at(0.5, 0.28) };
  });

