    const a = p.alpha * fade * (reducedMotion ? 0.75 : 1);
    g.addColorStop(0, `rgba(240, 220, 200, ${a})`);
    g.addColorStop(0.4, `rgba(210, 185, 165, ${a * 0.5})`);
    g.addColorStop(1, "rgba(180, 160, 140, 0)");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(
      px,
      py,
      radius,
      radius * (1.15 + p.life * 0.35),
      0,
      0,
      Math.PI * 2
    );
    ctx.fill();
  }

